users = [{'username': 'admin', 'password_hash': 'S3cretHash!'},
         {'username': 'mitali', 'password_hash': 'hunter2Hash'}]

def vulnerable_login(username, password):
    # Simulates concatenation: '--' truncates the password check
    if username.endswith("' --") or username.endswith("'--"):
        return users[0]  # password check discarded -> auth bypass
    for u in users:
        if u['username'] == username and u['password_hash'] == password:
            return u
    return None

def safe_login(username, password):
    # Parameterized: username compared as an exact literal, no structure leak
    for u in users:
        if u['username'] == username and u['password_hash'] == password:
            return u
    return None

payload = "admin' --"
print('VULNERABLE with payload:', vulnerable_login(payload, 'wrong'))
print('SAFE with same payload:', safe_login(payload, 'wrong'))

